import re

def tokenize(text):
    text = text.lower()
    result = re.findall(r"[a-z0-9']+", text)
    return result

def tokens_and_types(text):
    tokens = tokenize(text)
    count_tokens = 0
    for t in tokens:
        count_tokens = count_tokens + 1
    unique_list = []
    for t in tokens:
        is_in = False
        for u in unique_list:
            if u == t:
                is_in = True
        if is_in == False:
            unique_list.append(t)
    count_types = 0
    for u in unique_list:
        count_types = count_types + 1
    return (count_tokens, count_types)

def top_words(text, k):
    tokens = tokenize(text)
    words_list = []
    counts = []
    for t in tokens:
        found = False
        for i in range(len(words_list)):
            if words_list[i] == t:
                counts[i] = counts[i] + 1
                found = True
        if found == False:
            words_list.append(t)
            counts.append(1)
    combined = []
    for i in range(len(words_list)):
        combined.append([words_list[i], counts[i]])
    for i in range(len(combined)):
        for j in range(i + 1, len(combined)):
            if combined[j][1] > combined[i][1] or (combined[j][1] == combined[i][1] and combined[j][0] < combined[i][0]):
                temp = combined[i]
                combined[i] = combined[j]
                combined[j] = temp
    result = []
    for i in range(k):
        if i < len(combined):
            result.append((combined[i][0], combined[i][1]))
    return result

